function DualEditor({ a, b }: { a: User; b: User }) {
  const left = useForm({ key: ["user", a.id], data: a });
  const right = useForm({ key: ["user", b.id], data: b });

  return (
    <>
      <FormProvider form={left.form}><UserFields /></FormProvider>
      <FormProvider form={right.form}><UserFields /></FormProvider>
    </>
  );
}
